import json, urllib.request, urllib.error, time
from pathlib import Path
base='http://54.255.236.159:8012'
tok=json.loads(Path('/Users/mac/Desktop/CHcode/.claude/database/dc-platform.json').read_text())['token']
sql=Path('/Users/mac/Desktop/CHcode/ops_system/05.ads/ads_user_region_geo_d/ads_user_region_geo_d_daily.sql').read_text()
yaml=Path('/Users/mac/Desktop/CHcode/ops_system/05.ads/ads_user_region_geo_d/task.yaml').read_text()

def status():
  req=urllib.request.Request(base+'/api/v1/dev-sessions/index?scope=all&q=dev-20261102-002',
    headers={'Authorization':'Bearer '+tok})
  with urllib.request.urlopen(req, timeout=30) as r:
    items=json.loads(r.read()).get('items') or []
  for i in items:
    if i.get('code')=='dev-20261102-002':
      return i.get('publish_request_status'), i.get('i_can_publish_prod')
  return None, None

def publish():
  body={
    'env':'prod','project_code':171982119739200,'wf_code':174729508462400,
    'task_code':178050993799296,'new_sql':sql,'force':False,'task_yaml':yaml,
    'session_code':'dev-20261102-002',
  }
  req=urllib.request.Request(base+'/api/v1/dolphin/publish-task-sql', data=json.dumps(body).encode(),
    headers={'Authorization':'Bearer '+tok,'Content-Type':'application/json'}, method='POST')
  try:
    with urllib.request.urlopen(req, timeout=180) as r:
      return 200, r.read().decode()
  except urllib.error.HTTPError as e:
    return e.code, e.read().decode()

for i in range(6):
  st, can = status()
  print(time.strftime('%H:%M:%S'), 'status=', st, 'can=', can)
  if st=='pending' and can:
    code, body = publish()
    print('PUBLISH', code, body[:1500])
    break
  time.sleep(10)
else:
  print('still blocked after poll')
